"""Derive SkyyRebirth/build_skyyrebirth_0.3.5.py from SkyyRebirth/build_skyyrebirth_0.3.4.py (= the tools/deploy_set.py SET pin, GENERATED by
tools/rebirth_0_3_4_patch.py). rep(old, new) with asserted anchors; 0.3.4 stays untouched; its line endings are kept; every change is checked
at the end to prove nothing else changed.
Run:  python tools/rebirth_0_3_5_patch.py   then   python SkyyRebirth/build_skyyrebirth_0.3.5.py   (NO --deploy: coordinated deploy)
Test: python SkyyRebirth/test_skyyrebirth_0.3.5.py --dir tools/dev/scratch/<yours>/rb   (bare JVM, -Xverify:all)

0.3.5 (2026-10-16) = MENU PATTERN sweep S4: /rebirth (the Nexus of the Void) ON THE KIT 1.7 HUB PAGE (research/Menu-Pattern.md 3 + rules
7 / 8; recipe tools/HUBS-CONTRACT.md 'Kit 1.7' -> 'How to move a page'). Skyy (docs/answered/ui.md 2026-10-16): "Double check every menu
and make sure it's fully and completely built out / designed properly in the cohesive menu system we made. I never want to have to use a
back button. The menus at the top should always be there for easy navigation." + popups: every hub page Home size 1600 x 980, row 2 big
like Teleport; rule 8 names Rebirth ("EVERY page and window - hubs, the Void, Requip, Rebirth, ... - shows row 1 (hubs) + row 2 (that hub's
tabs)"). Optional cut M14 (Rebirth as a Profiles sub-tab) is OFF: Rebirth puts NO contract tab (the kit HUB_TABS is frozen). LAYOUT ONLY -
no rebirth / tree / Continue / data / command / setting change.
  1. THE PAGE = SUI.hub_page("SkyyRb", "character", sub=True) 1600 x 980 (0.1 - 0.3.4: a 1120 x 952 decorated window with no hub bars):
     the title bar (Character + the X), row 1 (Home + the 7 hubs) and row 2 (the Character tabs, PROFILES selected - rebirth is per profile)
     from HubBar.page17 (the kit's HubBar, install_hub_bar row + page, now in this jar); the clicks through HubBar.route FIRST (row 1 sends
     hub:h:<id> - Character itself = "self" = back to the rebirth view; row 2 hub:<tab> opens that tab - Profiles included; the X closes).
  2. THE ONE SUB-TAB ROW (the kit's 150 px small buttons = HubBar.subTab's markup, the active one Primary): YOUR REBIRTH (the rebirth
     view) | TREE NODE (shown while a node is open). In the node view YOUR REBIRTH sends "back" (0.3.4's Back button, gone - rule 8); the
     row's right side holds the live hint line (0.3.4: the canvas footer, tree.rowNeed live).
  3. THE CONTENT (1552 x 734): the left panel = the detail panel (SUI.DETAIL_W 456; 0.3.4: 260) with the same two views (the rebirth view:
     requirements, gains, Rebirth / Continue, Close; the node view: the node, Buy, your points) + the tree canvas 1080 x 734 (0.3.4:
     810 x 880): the 88 discs, 8 chips and the Nexus as before, the outer rows a little closer (radii 169 / 218 / 254 / 303 / 342; 0.3.4:
     169 / 221 / 274 / 325 / 371) so the whole tree fits the lower canvas; every gap still >= 6 px (asserted).
  4. DANGEROUS ACTIONS stay in the page: Rebirth and Continue keep the click-twice confirm (the first press arms for 10 s, the second 0.8 -
     10 s later starts it; Continue then calls bazaar:fn:closeall / ah:fn:closeall exactly as 0.3.4). No pop-up window: none is needed.
  Build-time: both views previewed through the kit (hub_page_preview + the view) -> check_page, assert_proven, check_sky_paths,
  assert_menu_page (1600 x 980, rows 1 + 2, one sub row, no back / menu button, no pager, the content fits). The jar now ships the kit's 59
  Sky Window files (SUI.kit_texture_files; IncludesAssetPack true). ROLLBACK to 0.3.4: safe (layout only; the old window comes back).
"""
import difflib
import os
import sys

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
sys.path.insert(0, os.path.join(ROOT, "tools"))
import skyyui as SUI

assert SUI.KIT_PAGE_VERSION == "1.7" and SUI.HUB_PAGE_IW == 1552 and SUI.DETAIL_W == 456, "kit skyyui 1.7 (hub_page)"

src = os.path.join(ROOT, "SkyyRebirth", "build_skyyrebirth_0.3.4.py")
dst = os.path.join(ROOT, "SkyyRebirth", "build_skyyrebirth_0.3.5.py")
raw = open(src, "rb").read()
NL = "\r\n" if b"\r\n" in raw else "\n"
assert NL == "\n" or raw.count(b"\r\n") == raw.count(b"\n"), "mixed line endings in 0.3.4"
s = raw.decode("utf8").replace("\r\n", "\n")
LF = "\n"
S0 = s
assert 'VERSION = "0.3.4"' in s and "GENERATED by tools/rebirth_0_3_4_patch.py" in s and "SUI.hub_page(" not in s, "not the generated 0.3.4"
CMD0, SYS0 = s.count("registerCommand("), s.count("registerSystem(")
OLDS = []


def rep(old, new, count=1):
    global s
    n = s.count(old)
    assert n == count, "anchor count %d (want %d): %s" % (n, count, old[:160])
    s = s.replace(old, new)
    OLDS.append(old)


HEAD = open(__file__, encoding="utf8").read().split('"""')[1]
NOTE = HEAD[HEAD.index("0.3.5 (2026-10-16)"):].rstrip() + "\n"

# ---------------------------------------------------------------- docstring + version
rep('''"""SkyyRebirth 0.3.4 - build script (javassist via jpype). GENERATED by tools/rebirth_0_3_4_patch.py from build_skyyrebirth_0.3.3.py (itself
generated by tools/rebirth_0_3_3_patch.py from 0.3.2, generated by tools/rebirth_0_3_2_patch.py from 0.3.1, generated by tools/rebirth_0_3_1_patch.py
''',
    '''"""SkyyRebirth 0.3.5 - build script (javassist via jpype). GENERATED by tools/rebirth_0_3_5_patch.py from build_skyyrebirth_0.3.4.py (itself
generated by tools/rebirth_0_3_4_patch.py from 0.3.3, generated by tools/rebirth_0_3_3_patch.py from 0.3.2, generated by tools/rebirth_0_3_2_patch.py
from 0.3.1, generated by tools/rebirth_0_3_1_patch.py
''')
rep('''Run:   python SkyyRebirth/build_skyyrebirth_0.3.4.py   -> SkyyRebirth/SkyyRebirth-0.3.4.jar   (no --deploy: tools/deploy_set.py installs the set)
Check: python SkyyRebirth/test_skyyrebirth_0.3.4.py --dir tools/dev/scratch/<yours>/rb   (bare JVM, -Xverify:all, every code path executed)

''', '''Run:   python SkyyRebirth/build_skyyrebirth_0.3.5.py   -> SkyyRebirth/SkyyRebirth-0.3.5.jar   (no --deploy: tools/deploy_set.py installs the set)
Check: python SkyyRebirth/test_skyyrebirth_0.3.5.py --dir tools/dev/scratch/<yours>/rb   (bare JVM, -Xverify:all, every code path executed)

''' + NOTE + '''  CHECKED: SkyyRebirth/test_skyyrebirth_0.3.5.py.

''')
rep('VERSION = "0.3.4"\n', 'VERSION = "0.3.5"\n')

# ---------------------------------------------------------------- engine probes: the kit HubBar (CommandManager) + CustomUIPage.playerRef
rep('''             ("com.hypixel.hytale.server.core.command.system.AbstractCommand", "addSubCommand"), (T["ATY"], "INTEGER"), (T["ATY"], "STRING")):
    B.probe(pool, c, m)''', '''             ("com.hypixel.hytale.server.core.command.system.AbstractCommand", "addSubCommand"), (T["ATY"], "INTEGER"), (T["ATY"], "STRING"),
             # 0.3.5: the kit 1.7 HubBar (row 1 / row 2 open a page through CommandManager) + the page's own PlayerRef for HubBar.route
             (SUI.HUB_TYPES["CMGR"], "get"), (SUI.HUB_TYPES["CMGR"], "handleCommand"), (T["PAGE"], "playerRef")):
    B.probe(pool, c, m)''')

# ---------------------------------------------------------------- the page markup: the kit 1.7 hub page
rep('''# ================= RbUI: the page markup (tools/skyyui.py - vanilla look; inline only; ids SkyyRb..., no underscores). 0.3: the left panel has
# TWO views (one is appended at a time, Java if/else): view 0 = "Your rebirth" (requirements, gains, Rebirth / Continue, Close), view 1 = the
# selected node (what it does, cost, points, Buy, Back). The 88 tree discs are Groups with a runtime colour, each holding a Button (the
# vanilla list-row hover) with the level digit.
P = "SkyyRb"
PW, PH = 1120, 952
sh = SUI.page_shell(P, PW, PH, title="Rebirth - Nexus of the Void", kind="decorated", layout="Left")
ap = sh.appends
LW, GAP = 260, 16
CW, CH = sh.inner_w - LW - GAP, sh.inner_h
assert (CW, CH) == (810, 880), (CW, CH)
ap.append((sh.body, SUI.panel(P + "Left", "simple", w=LW, h=CH, layout="Top")))
ap.append((sh.body, SUI.spacer(w=GAP)))
ap.append((sh.body, SUI.panel(P + "Canvas", "well", w=CW, h=CH, layout=None, pad=0)))''',
    '''# ================= RbUI: the page markup (tools/skyyui.py - vanilla look; inline only; ids SkyyRb..., no underscores). 0.3: the left panel has
# TWO views (one is appended at a time, Java if/else): view 0 = "Your rebirth" (requirements, gains, Rebirth / Continue, Close), view 1 = the
# selected node (what it does, cost, points, Buy). The 88 tree discs are Groups with a runtime colour, each holding a Button (the
# vanilla list-row hover) with the level digit.
# 0.3.5 MENU PATTERN (kit 1.7): the page is SUI.hub_page (1600 x 980, rows 1 + 2 = HubBar.page17, Character / Profiles selected, the ONE
# sub-tab row YOUR REBIRTH | TREE NODE + the hint line), the content 1552 x 734 = the detail panel (DETAIL_W 456) + the tree canvas.
P = "SkyyRb"
HUB, HUB_TAB = "character", "profiles"     # rebirth is per profile: row 2 shows the Character tabs with Profiles selected (no contract tab)
sh = SUI.hub_page(P, HUB, sub=True, body_id=P + "B", content_id=P + "Body", content_layout="Left")
assert (sh.w, sh.h, sh.content_w, sh.content_h, sh.content, sh.sub, sh.foot) == (1600, 980, 1552, 734, "SkyyRbBody", "SkyyRbSub", None), \\
    "0.3.5: the hub page"
ap = sh.appends
LW, GAP = SUI.DETAIL_W, 16
CW, CH = sh.content_w - LW - GAP, sh.content_h
assert (CW, CH) == (1080, 734), (CW, CH)
ap.append((sh.content, SUI.panel(P + "Left", "simple", w=LW, h=CH, layout="Top")))
ap.append((sh.content, SUI.spacer(w=GAP)))
ap.append((sh.content, SUI.panel(P + "Canvas", "well", w=CW, h=CH, layout=None, pad=0)))''')
# the node view: no Back button (rule 8) - the sub-tab YOUR REBIRTH sends "back"
rep('''apN.append((L, SUI.group(P + "NvBtns2", layout="Left", w=BW, h=SUI.BTN_H, anchor={"top": 8})))
apN.append(("#" + P + "NvBtns2", SUI.button(P + "Back", "Back", "secondary", w=BW, sound="cancel")))
''', '')
# the tree: the outer rows closer (the canvas is 734 high; 0.3.4: 880)
rep('''RADII = [169, 221, 274, 325, 371]''', '''RADII = [169, 218, 254, 303, 342]     # 0.3.5: the outer rows closer - the 734 px canvas (0.3.4: 169 / 221 / 274 / 325 / 371 in 880); rows 2 -> 3 and 4 -> 5 change their side offsets, so they sit closer''')
# the canvas footer becomes the sub-tab row's hint line (both views)
rep('''ap.text(CV, P + "Foot", J_("this.foot", "Click a node to see it on the left. 8 levels in a row open the next row."), "caption", w=CW, h=22,
        align="Center", anchor={"left": 0, "top": CH - 30})   # fix round: tree.rowNeed is live
assert SUI.text_lines("Click a node to see it on the left - 10 levels in a row open the next row - click the Nexus to rebirth.", CW - 8, SUI.fs(12)) == 1
''', '''# 0.3.5: THE ONE SUB-TAB ROW (the kit's 150 px small buttons = HubBar.subTab's markup, SUI.sub_tab_markup; the active one Primary) +
# the live hint line (0.3.4: the canvas footer). Rebirth view: YOUR REBIRTH (selected, unbound) + room for the second tab; node view: YOUR
# REBIRTH (a = "back" = 0.3.4's Back button) | TREE NODE (selected, unbound).
SUB_LABELS = ["Your rebirth", "Tree node"]
SUB_ROW_W = SUI.assert_sub_tabs_fit(SUB_LABELS)
HINT_GAP = 16
HINT_W = sh.content_w - SUB_ROW_W - HINT_GAP
SUBR = SUI.Appends([("#" + P + "Sub", SUI.sub_tab_markup(P, 0, SUB_LABELS[0], True)),
                    ("#" + P + "Sub", SUI.group(None, layout="Left", w=SUB_ROW_W - SUI.SUB_TAB_W, h=SUI.SUB_TAB_H))])
SUBN = SUI.sub_tabs_preview(P, SUB_LABELS, 1)
for _sa in (SUBR, SUBN):
    _sa.append(("#" + P + "Sub", SUI.spacer(w=HINT_GAP)))
    _sa.text("#" + P + "Sub", P + "Hint", J_("this.foot", "Click a node to see it on the left. 8 levels in a row open the next row."), "caption",
             w=HINT_W, h=SUI.SUB_TAB_H)   # fix round: tree.rowNeed is live
assert SUI.text_lines("Click a node to see it on the left - 10 levels in a row open the next row - click the Nexus to rebirth.", HINT_W - 8, SUI.fs(12)) == 1
apR[0:0] = list(SUBR)
apR.sets[0:0] = list(SUBR.sets)
apN[0:0] = list(SUBN)
apN.sets[0:0] = list(SUBN.sets)
''')
rep('''SUI.assert_proven(sh.appends.markups() + apR.markups() + apN.markups(), allow=("tooltip",), what="SkyyRebirth /rebirth page")
PAGE_JAVA = sh.java("b")''', '''SUI.assert_proven(sh.appends.markups() + apR.markups() + apN.markups(), allow=("tooltip",), what="SkyyRebirth /rebirth page")
# 0.3.5: each view's WHOLE page as the build draws it (the kit's Python twins of HubBar.page17 + the view) through the kit 1.7 checks
HUB_TABS_NOW = [(r[0], SUI.hub_tab_label(HUB, r[0])) for r in SUI.hub_page_tabs(HUB)]
assert HUB_TAB in [t_[0] for t_ in HUB_TABS_NOW], HUB_TABS_NOW
for _vn, _ap_ in (("rebirth view", apR), ("node view", apN)):
    _pv = SUI.hub_page_preview(sh, tabs=HUB_TABS_NOW, my_tab=HUB_TAB)
    _pv.extend(_ap_)
    SUI.check_page(_pv, P)
    SUI.assert_proven(_pv.markups(), allow=("tooltip",), what="SkyyRebirth 0.3.5 " + _vn)
    SUI.check_sky_paths(_pv, tab_icons=True)
    for _pick in (0, 1):     # SUI.assert_menu_page cannot render a choose() Choice (kit 1.7): each runtime variant is checked as its own page
        _flat = SUI.Appends([(p_, mk_.variants()[_pick] if isinstance(mk_, SUI.Choice) else mk_) for p_, mk_ in _pv])
        _flat.sets = list(_pv.sets)
        _mi = SUI.assert_menu_page(_flat, sh, what="SkyyRebirth 0.3.5 %s (variant %d)" % (_vn, _pick))
        assert _mi["rows"] == 2 and _mi["subs"] == 1, _mi
HUB_JAVA = SUI.java_hub_page(sh, HUB_TAB, cls="@PKG@.HubBar", uuid="this.me")
assert HUB_JAVA == '@PKG@.HubBar.page17(b, ev, "SkyyRb", "character", "profiles", 1552, this.me, 2);', HUB_JAVA
PAGE_JAVA = sh.java("b") + "\\n" + HUB_JAVA     # 0.3.5: the hub page shell, then rows 1 + 2 + the X binding''')

# the left panel rows: the detail panel is 456 wide (0.3.4: 260) - each row holds the most lines its LONGEST text takes at the new width
# (never more than 0.3.4's line count), so the node view fits the 734 px content
rep('''    ROW_H[_r] = int(math.ceil(_lh * _ln))
    for _t in _txts:''', '''    _need = max(SUI.text_lines(_t, LIN_W, SUI.fs(_sz), bold=_bd) for _t in _txts)   # 0.3.5: the lines the longest text takes at 456 px
    ROW_H[_r] = int(math.ceil(_lh * min(_ln, _need)))
    for _t in _txts:''')

# ---------------------------------------------------------------- the kit's HubBar in this jar (before RbPage compiles against it)
rep('''# ================= RbPage: /rebirth (0.3: the tree is live; Continue)
page = mk("RbPage", T["PAGE"])''', '''# ================= 0.3.5: the kit 1.7 HubBar (row 1 + row 2 + the X: page17 / route) in OUR package (cross-jar classes are not allowed)
hubb = SUI.install_hub_bar(pool, PKG + ".HubBar", CtField, CtNewMethod, row=True, page=True)

# ================= RbPage: /rebirth (0.3: the tree is live; Continue)
page = mk("RbPage", T["PAGE"])''')
# the node view: the sub-tab YOUR REBIRTH = 0.3.4's Back (the same action)
rep('''    ev.addEventBinding(@BT@.Activating, "#SkyyRbBack", @EVD@.of("a", "back"));''',
    '''    ev.addEventBinding(@BT@.Activating, "#SkyyRbSub0", @EVD@.of("a", "back"));   // 0.3.5: the sub-tab YOUR REBIRTH (0.3.4: the Back button)''')
# the clicks: HubBar.route FIRST (row 1 hub:h:<id>, row 2 hub:<tab>, the X hub:close)
rep('''public void handleDataEvent(@REF@ ref, @ST@ st, String data) {
  String a = act(data);
  if (a == null) return;
''', '''public void handleDataEvent(@REF@ ref, @ST@ st, String data) {
  String a = act(data);
  if (a == null) return;
  if (a.startsWith("hub:")) {   // 0.3.5 kit 1.7: row 1 (hub:h:<id>; Character = self), row 2 (hub:<tab>; Profiles opens Profiles), the X (hub:close)
    @PR@ pr = null;
    if (!this.testMode) pr = this.playerRef;
    String hr = @PKG@.HubBar.route(pr, data, "character", null);
    this.last = "=hub " + hr;
    if (hr == null) return;
    if (hr.equals("close")) { if (this.testMode) return; this.gone = true; close(); return; }
    if (hr.equals("self")) { this.view = 0; this.sel = -1; this.status = null; this.armedAt = 0L; if (!this.testMode) rebuild(); return; }   // = Back
    if (!this.testMode && !hr.equals("bridge") && !hr.equals("command") && !hr.equals("back")) @PKG@.RbTx.tell(String.valueOf(this.me), "[Rebirth] That page could not open right now - try again.", "#ff6b6b");
    return;
  }
''')
rep('''ALL = [cfg, load, st, mth, tree, rbj, jrn, fnc, pub, tick, chk, tel, tx, run_, page, job, rfr, cmd, adm, admv, admx, admp, admf, admc, pl]   # 0.3.1: + 3 sub-commands''',
    '''ALL = [cfg, load, st, mth, tree, rbj, jrn, fnc, pub, tick, chk, tel, tx, run_, hubb, page, job, rfr, cmd, adm, admv, admx, admp, admf, admc, pl]   # 0.3.1: + 3 sub-commands; 0.3.5: + HubBar''')

# ---------------------------------------------------------------- the jar: the kit's Sky Window art
rep('''man["IncludesAssetPack"] = False
B.assemble(jar, man, OUT)''', '''man["IncludesAssetPack"] = True       # 0.3.5: the jar carries the Sky Window kit art (0.3.4: false - no assets)
# 0.3.5: the Sky Window kit art - all 59 files, byte-identical in every hub jar (sha256-pinned by the kit; HUBS-CONTRACT 2.7), under
# Common/UI/Custom/SkyyKit/ only (a texture outside Common/UI/Custom disconnects the client - probe k1b, 2026-10-15)
_kit = SUI.kit_texture_files()
assert len(_kit) == len(SUI.SKY_FILES) == 59 and all(p_.startswith("Common/UI/Custom/SkyyKit/") and ".." not in p_ for p_ in _kit), "0.3.5: the kit art"
B.assemble(jar, man, OUT, _kit)
assert SUI.check_jar_kit(jar, need=("Header", "HeaderOrnament", "Tab", "Tab_Selected", "Close", "Frame_Character", "Tertiary")) == 59, "0.3.5: the jar's kit art"''')

# ---------------------------------------------------------------- checks
assert "page_shell(" not in s.split("# ================= RbUI")[1], "0.3.5: no old window shell left"
_code = s.split('"""', 2)[2]     # the code after the docstring
assert (_code.count("SUI.hub_page("), _code.count("HubBar.route("), _code.count("install_hub_bar(")) == (1, 1, 1) and '"Back"' not in _code,     ("0.3.5 hub page", _code.count("SUI.hub_page("), _code.count("HubBar.route("), _code.count("install_hub_bar("), '"Back"' in _code)
assert (s.count("registerCommand("), s.count("registerSystem(")) == (CMD0, SYS0), "0.3.5: no command / system change"
for _k in ("bazaar:fn:closeall", "ah:fn:closeall", "RbTx.playerStart(this.me, w, cont)", 'a.equals("rbcont")', 'a.equals("back")', 'a.equals("buy")',
           'a.equals("close")', 'a.equals("nexus")'):
    assert _code.count(_k) == S0.split('"""', 2)[2].count(_k), "0.3.5: %s unchanged" % _k
_a, _b = S0.split(LF), s.split(LF)
_hunks = [op for op in difflib.SequenceMatcher(None, _a, _b, autojunk=False).get_opcodes() if op[0] != "equal"]
_gone = [(i, _a[i]) for op in _hunks for i in range(op[1], op[2])]
_allowed = set()
for _o in OLDS:
    _allowed.update(_o.split(LF))
_bad = [(i, ln) for i, ln in _gone if ln not in _allowed and not any(_o in ln for _o in OLDS if LF not in _o)]
assert not _bad, "0.3.4 lines changed outside the planned places: %r" % _bad[:5]
if os.path.exists(dst):
    os.remove(dst)
compile(s, dst, "exec")
open(dst, "wb").write(s.replace(LF, NL).encode("utf8"))
print("wrote", dst, len(s), "chars;", len(_hunks), "diff hunks vs 0.3.4,", len(_gone), "0.3.4 lines replaced;", len(OLDS), "anchors")
